// Code node "Queue bookings" (run once for all items).
// Input: appointments PracticeQ reports as updated since yesterday (one item each, or one
// empty item when there are none). Output: one item per client whose summary is due now.
//
// A client enters the queue when a new open appointment is booked for them. Any further
// change to that client's appointments while they wait (another booking, a reschedule, a
// cancellation) pushes the send time back, so the email goes out once the schedule has been
// quiet for `bufferMinutes`. Edits to clients who are not waiting (marking a visit attended,
// invoicing) never trigger an email.
const s = $('Settings').first().json;
const state = $getWorkflowStaticData('global');
const OPEN = ['Confirmed', 'WaitingConfirmation'];
const now = Date.now();
const bufferMs = Number(s.bufferMinutes) * 60000;
state.pending = state.pending || {};

const rows = $input.all().map((i) => i.json).filter((r) => r && r.Id);

if (state.cursor === undefined) {
  // First run: watch from now on, never email for changes made before the switch-on.
  state.cursor = rows.reduce((m, r) => Math.max(m, Number(r.LastModified) || 0), now);
  return [];
}

const since = state.cursor;
let cursor = since;
for (const r of rows) {
  const modified = Number(r.LastModified) || 0;
  if (modified <= since) continue;
  cursor = Math.max(cursor, modified);

  const key = String(r.ClientId);
  const waiting = state.pending[key];
  const newBooking = Number(r.DateCreated) > since && OPEN.includes(r.Status) && Number(r.StartDate) > now;
  if (!waiting && !newBooking) continue;

  state.pending[key] = {
    clientId: r.ClientId,
    email: r.ClientEmail || (waiting && waiting.email) || '',
    name: r.ClientName || (waiting && waiting.name) || '',
    dueAt: Math.max(waiting ? waiting.dueAt : 0, modified + bufferMs),
    attempts: waiting ? waiting.attempts : 0,
  };
}
state.cursor = cursor;

const due = [];
for (const [key, p] of Object.entries(state.pending)) {
  if (p.dueAt <= now) {
    due.push(p);
    delete state.pending[key];
  }
}
return due.map((p) => ({ json: p }));

// Code node "Build emails" (run once for all items).
// Input: every appointment from today on for each due client (from "Get upcoming").
// Output: one item per email to send, with the GHL recipient, subject and HTML body.
const s = $('Settings').first().json;
const due = $('Queue bookings').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.Id);
const OPEN = ['Confirmed', 'WaitingConfirmation'];
const now = Date.now();
const live = s.mode === 'live';

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (ms, opts) => new Intl.DateTimeFormat('en-US', { timeZone: s.timezone, ...opts }).format(new Date(ms));

const out = [];
for (const c of due) {
  // The PracticeQ "client" filter is a partial name/email match, so keep only this client's rows.
  const seen = new Set();
  const appts = rows
    .filter((r) => String(r.ClientId) === String(c.clientId) && OPEN.includes(r.Status) && Number(r.StartDate) > now)
    .filter((r) => !seen.has(r.Id) && seen.add(r.Id))
    .sort((a, b) => a.StartDate - b.StartDate);
  if (!c.email || !appts.length) continue; // nothing to send (no email on file, or all cancelled)

  const to = live ? c.email : s.testEmail;
  if (!to) continue;

  const first = esc(String(c.name).trim().split(/\s+/)[0] || 'there');
  const lines = appts.slice(0, 40).map((a) => `
    <tr>
      <td style="padding:8px 12px;border-bottom:1px solid #eee;white-space:nowrap">${fmt(a.StartDate, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}</td>
      <td style="padding:8px 12px;border-bottom:1px solid #eee;white-space:nowrap">${fmt(a.StartDate, { hour: 'numeric', minute: '2-digit' })}</td>
      <td style="padding:8px 12px;border-bottom:1px solid #eee">${esc(a.ServiceName)}${a.Status === 'WaitingConfirmation' ? ' <em>(awaiting confirmation)</em>' : ''}</td>
      <td style="padding:8px 12px;border-bottom:1px solid #eee">${esc(a.PractitionerName)}</td>
      <td style="padding:8px 12px;border-bottom:1px solid #eee">${esc(a.LocationName)}</td>
    </tr>`).join('');
  const more = appts.length > 40 ? `<p>…and ${appts.length - 40} more.</p>` : '';

  const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#222;line-height:1.5">
  <p>Hi ${first},</p>
  <p>Here ${appts.length === 1 ? 'is your upcoming appointment' : `are your ${appts.length} upcoming appointments`} with ${esc(s.practiceName)}:</p>
  <table style="border-collapse:collapse;font-size:14px">
    <tr style="text-align:left;background:#f5f5f5">
      <th style="padding:8px 12px">Date</th><th style="padding:8px 12px">Time</th><th style="padding:8px 12px">Visit</th><th style="padding:8px 12px">With</th><th style="padding:8px 12px">Location</th>
    </tr>${lines}
  </table>${more}
  <p>If anything looks wrong or you need to make a change, please call us at ${esc(s.practicePhone)} or reply to this email.</p>
  <p>See you soon,<br>${esc(s.practiceName)}</p>
</div>`;

  const subject = `Your upcoming appointments at ${s.practiceName}`;
  out.push({
    json: {
      ...c,
      to,
      count: appts.length,
      subject: live ? subject : `[TEST for ${c.name} <${c.email}>] ${subject}`,
      html,
    },
  });
}
return out;

// Code node "Record results" (run once for all items).
// Input: the GHL send responses, one per "Build emails" item in the same order (the send
// nodes continue on error, so a failure is an item with an `error` field).
// A failed send is retried 10 minutes later, up to 3 attempts in total. Output is a log line
// per email, visible in the n8n execution.
const state = $getWorkflowStaticData('global');
state.pending = state.pending || {};
const emails = $('Build emails').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
const MAX_ATTEMPTS = 3;

return emails.map((c, i) => {
  const r = results[i] || { error: 'no response' };
  const base = { clientId: c.clientId, to: c.to, appointments: c.count };
  if (!r.error) return { json: { ...base, status: 'sent', messageId: r.messageId || r.emailMessageId || null } };

  const attempts = (c.attempts || 0) + 1;
  const key = String(c.clientId);
  const retry = attempts < MAX_ATTEMPTS;
  if (retry && !state.pending[key]) {
    state.pending[key] = { clientId: c.clientId, email: c.email, name: c.name, dueAt: Date.now() + 10 * 60000, attempts };
  }
  const error = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  return { json: { ...base, status: retry ? 'failed, will retry' : 'failed, gave up', attempts, error } };
});
